mapper.select:
select id, user_id, provider, identifier, password_hash, verified_at, created_at, updated_at
from cm_auth_identities
where provider = #{provider}
  and identifier = #{identifier}
limit 1

mapper.update:
update cm_auth_identities
set password_hash = #{passwordHash}
where id = #{id}

mapper.select:
select id, challenge_token as challengeToken, expires_at as expiresAt, status
from cm_user_security_challenges
where user_id = #{userId}
  and action = #{action}
  and identity_id = #{identityId}
  and status = 'pending'
  and expires_at > now()
order by created_at desc limit 1

mapper.update:
update cm_user_security_challenges
set status = 'consumed',
    consumed_at = now(),
    updated_at = now()
where user_id = #{userId}
  and action = #{action}
  and challenge_token = #{challengeToken}
  and status = 'verified'
  and expires_at > now()

update cm_user_security_challenges
set status = 'expired', updated_at = now()
where user_id = #{userId}
  and action = #{action}
  and challenge_token = #{challengeToken}
  and status = 'verified'
  and expires_at <= now()
